/* JPT PARTNER FINAL TOUCH V2
   One-file final visual layer.
   - Premium black + gold dashboard
   - Strong green ONLINE / red OFFLINE glow
   - Embedded Punjabi Sardar logo artwork
   - Embedded food promotion posters (no extra image files required)
   - Live metric syncing from existing dashboard IDs
   - Existing Supabase/order/menu/business logic remains untouched
*/
(function(){
  'use strict';
  if(window.__JPT_PARTNER_FINAL_TOUCH_V2__) return;
  window.__JPT_PARTNER_FINAL_TOUCH_V2__=true;

  const ROOT='jptFinalTouchHomeV2';
  const STYLE='jptFinalTouchStyleV2';
  const LOGO='data:image/png;base64,';
  const POSTERS=['data:image/png;base64,','data:image/png;base64,'];

  const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));

  function addStyle(){
    if(document.getElementById(STYLE)) return;
    const s=document.createElement('style');
    s.id=STYLE;
    s.textContent=`
      #${ROOT}{box-sizing:border-box;display:block;max-width:1100px;margin:auto;background:#030303;color:#fff;padding:0 12px 118px;min-height:100vh}
      #${ROOT} *{box-sizing:border-box}
      .jpt-v2-head{position:relative;margin:0 -12px 14px;padding:12px 12px 10px;background:linear-gradient(180deg,#050505,#0b0b08);border-bottom:1px solid #4d3a12;box-shadow:0 8px 30px #000}
      .jpt-v2-headrow{display:flex;align-items:center;gap:10px}
      .jpt-v2-menu,.jpt-v2-bell{width:46px;height:46px;flex:0 0 46px;border:1px solid #6a521a;border-radius:14px;background:#080808;color:#f0c64d;font-size:24px;display:grid;place-items:center}
      .jpt-v2-logo{width:64px;height:64px;flex:0 0 64px;border-radius:50%;object-fit:cover;border:2px solid #e9bd43;background:#050505;box-shadow:0 0 22px rgba(240,198,77,.30)}
      .jpt-v2-brand{min-width:0;flex:1}
      .jpt-v2-brand b{display:block;color:#f2c84f;font-size:22px;font-weight:950;line-height:1.05;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
      .jpt-v2-brand span{display:block;color:#aaa;font-size:10px;letter-spacing:1px;margin-top:4px}
      .jpt-v2-context{margin:8px 0 8px;text-align:center;color:#e6b93e;font-weight:900;font-size:12px}
      .jpt-v2-controls{display:flex;gap:8px;overflow:auto}
      .jpt-v2-controls>*{flex:0 0 auto}
      .jpt-v2-controls select{min-width:260px!important}
      .jpt-v2-poster{position:relative;height:205px;border-radius:19px;overflow:hidden;border:2px solid #d5aa31;background:#070707;box-shadow:0 0 26px rgba(238,190,55,.16);margin:10px 0 16px}
      .jpt-v2-poster img{width:100%;height:100%;display:block;object-fit:cover}
      .jpt-v2-poster button{position:absolute;top:50%;transform:translateY(-50%);z-index:3;width:38px;height:38px;border-radius:50%;border:1px solid #e9bd43;background:#050505aa;color:#fff;font-size:25px}
      .jpt-v2-prev{left:9px}.jpt-v2-next{right:9px}
      .jpt-v2-dots{position:absolute;z-index:4;bottom:8px;left:50%;transform:translateX(-50%);display:flex;gap:7px}
      .jpt-v2-dots i{width:8px;height:8px;border-radius:50%;background:#777;border:1px solid #222}
      .jpt-v2-dots i.on{background:#f0c64d;box-shadow:0 0 8px #f0c64d}
      .jpt-v2-status-host{position:relative}
      .jpt-v2-status-host #statusBox{position:relative!important;overflow:hidden!important;border-radius:20px!important;min-height:150px!important;padding:20px!important;margin:0 0 15px!important;transition:.35s!important}
      .jpt-v2-status-host #statusBox.online{
        background:radial-gradient(circle at 15% 50%,rgba(0,255,94,.24),transparent 45%),linear-gradient(110deg,#031508,#071d0d 48%,#020503)!important;
        border:2px solid #00ff62!important;
        box-shadow:0 0 10px rgba(0,255,98,.95),0 0 30px rgba(0,255,98,.62),0 0 65px rgba(0,255,98,.34),inset 0 0 35px rgba(0,255,98,.14)!important;
      }
      .jpt-v2-status-host #statusBox.offline{
        background:radial-gradient(circle at 15% 50%,rgba(255,25,35,.24),transparent 45%),linear-gradient(110deg,#190304,#270507 48%,#080202)!important;
        border:2px solid #ff2633!important;
        box-shadow:0 0 10px rgba(255,38,51,.95),0 0 30px rgba(255,38,51,.62),0 0 65px rgba(255,38,51,.34),inset 0 0 35px rgba(255,38,51,.14)!important;
      }
      .jpt-v2-status-host #statusBox.online:before,.jpt-v2-status-host #statusBox.offline:before{content:"";position:absolute;inset:5px;border-radius:15px;pointer-events:none;opacity:.8;animation:jptGlow 1.8s ease-in-out infinite alternate}
      .jpt-v2-status-host #statusBox.online:before{border:1px solid #00ff62}
      .jpt-v2-status-host #statusBox.offline:before{border:1px solid #ff2633}
      @keyframes jptGlow{from{opacity:.35}to{opacity:1}}
      .jpt-v2-status-host #statusTitle{font-size:25px!important;font-weight:1000!important;text-transform:uppercase!important}
      .jpt-v2-status-host #statusText{font-size:13px!important;color:#eee!important}
      .jpt-v2-status-host .store{width:78px!important;height:78px!important;border-radius:50%!important;overflow:hidden!important;background:#030303!important;border:2px solid #e8bd43!important}
      .jpt-v2-status-host .store img{width:100%;height:100%;object-fit:cover}
      .jpt-v2-section{display:flex;justify-content:space-between;align-items:center;margin:14px 3px 9px}
      .jpt-v2-section b{color:#f0c64d;font-size:19px}
      .jpt-v2-section span{color:#777;font-size:11px}
      .jpt-v2-metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}
      .jpt-v2-metric{background:linear-gradient(145deg,#121212,#050505);border:1px solid #4a3813;border-radius:16px;padding:14px 8px;text-align:center;min-height:98px;box-shadow:inset 0 0 18px rgba(229,181,50,.035)}
      .jpt-v2-metric .num{color:#f0c64d;font-size:31px;font-weight:1000;line-height:1.1}
      .jpt-v2-metric .lbl{color:#bbb;font-size:11px;margin-top:7px}
      .jpt-v2-actions{display:grid;grid-template-columns:repeat(4,1fr);gap:9px}
      .jpt-v2-action{min-height:88px;border:1px solid #604817;border-radius:15px;background:linear-gradient(145deg,#151515,#070707);color:#fff;font-weight:900;font-size:11px;display:flex;flex-direction:column;justify-content:center;align-items:center;gap:6px;box-shadow:inset 0 0 18px rgba(216,174,66,.025)}
      .jpt-v2-action b{font-size:27px;color:#f1c64c}
      .jpt-v2-open{display:flex;align-items:center;justify-content:space-between;gap:10px;margin:14px 0;background:linear-gradient(90deg,#ffd95a,#d59f24);border-radius:15px;color:#111;padding:16px 18px;font-size:17px;font-weight:1000;box-shadow:0 8px 25px rgba(238,188,55,.23)}
      .jpt-v2-open button{border:0;background:transparent;font-weight:1000;font-size:14px;color:#111}
      .jpt-v2-bottom{position:fixed;left:10px;right:10px;bottom:10px;z-index:999;background:rgba(4,4,4,.97);border:1px solid #6a5018;border-radius:20px;padding:7px;display:grid;grid-template-columns:repeat(5,1fr);box-shadow:0 0 28px #000,0 0 14px rgba(216,174,66,.14)}
      .jpt-v2-bottom button{border:0;background:transparent;color:#aaa;border-radius:14px;padding:9px 3px;font-size:9px;font-weight:900}
      .jpt-v2-bottom button.active{background:#f0c64d;color:#111;box-shadow:0 0 18px rgba(240,198,77,.35)}
      .jpt-v2-bottom b{display:block;font-size:19px;margin-bottom:2px}
      @media(max-width:760px){
        #${ROOT}{padding-left:10px;padding-right:10px}
        .jpt-v2-logo{width:58px;height:58px;flex-basis:58px}
        .jpt-v2-brand b{font-size:20px}
        .jpt-v2-poster{height:190px}
        .jpt-v2-metrics{grid-template-columns:repeat(2,1fr)}
        .jpt-v2-actions{grid-template-columns:repeat(4,1fr)}
        .jpt-v2-status-host #statusBox{min-height:145px!important}
      }
    `;
    document.head.appendChild(s);
  }

  function srcMetric(id){return document.getElementById(id)?.textContent?.trim()||'—'}

  function getCode(){
    return String(window.activeOutlet||document.getElementById('outletSelect')?.value||localStorage.getItem('jpt_admin_outlet')||'');
  }

  async function getOutlet(){
    const code=getCode();
    let row=null;
    try{
      if(window.sb&&code){
        const r=await window.sb.from('outlets').select('code,name,logo_url,banner_url,status,is_active,accepting_orders').eq('code',code).maybeSingle();
        row=r.data||null;
      }
    }catch(e){}
    return row||{code:code||'JPT-001',name:document.getElementById('heroName')?.textContent||'Jeet Punjabi Tadka'};
  }

  function moveControls(root){
    const controls=document.querySelector('.top .controls');
    if(!controls)return;
    const wrap=document.createElement('div');
    wrap.className='jpt-v2-controls';
    while(controls.firstChild)wrap.appendChild(controls.firstChild);
    controls.parentNode?.remove();
    root.querySelector('.jpt-v2-head').appendChild(wrap);
  }

  function setLogo(statusStore){
    if(statusStore){
      statusStore.innerHTML='<img src="'+LOGO+'" alt="JPT Punjabi Sardar">';
    }
  }

  function build(outlet){
    const oldHome=document.getElementById('home');
    const oldHero=document.getElementById('hero');
    const oldGrid=document.querySelector('.grid');
    const top=document.querySelector('.top');
    if(!oldHome||!oldHero||!oldGrid)return;

    let root=document.getElementById(ROOT);
    if(!root){
      root=document.createElement('div');
      root.id=ROOT;
      document.querySelector('main.shell')?.before(root);
      if(!root.parentNode) document.body.appendChild(root);
    }

    const name=outlet.name||'Jeet Punjabi Tadka';
    const code=outlet.code||getCode();
    root.innerHTML=`
      <div class="jpt-v2-head">
        <div class="jpt-v2-headrow">
          <div class="jpt-v2-menu">☰</div>
          <img class="jpt-v2-logo" src="${LOGO}" alt="Punjabi Sardar logo">
          <div class="jpt-v2-brand"><b>${esc(name)}</b><span>RESTAURANT PARTNER APP • ${esc(code)}</span></div>
          <button class="jpt-v2-bell" id="jptV2Bell">🔔</button>
        </div>
        <div class="jpt-v2-context">${esc(name)} • ${esc(code)}</div>
      </div>

      <div class="jpt-v2-poster">
        <img id="jptV2Poster" src="${POSTERS[0]}" alt="Punjabi food promotion">
        <button class="jpt-v2-prev" id="jptV2Prev">‹</button>
        <button class="jpt-v2-next" id="jptV2Next">›</button>
        <div class="jpt-v2-dots"><i class="on"></i><i></i></div>
      </div>

      <div class="jpt-v2-status-host" id="jptV2StatusHost"></div>

      <div class="jpt-v2-section"><b>Today at your outlet</b><span>LIVE</span></div>
      <div class="jpt-v2-metrics">
        <div class="jpt-v2-metric"><div class="num" data-src="ordersCount">${esc(srcMetric('ordersCount'))}</div><div class="lbl">🧾 Orders Today</div></div>
        <div class="jpt-v2-metric"><div class="num" data-src="menuCount">${esc(srcMetric('menuCount'))}</div><div class="lbl">🍽️ Menu Items</div></div>
        <div class="jpt-v2-metric"><div class="num" data-src="offerCount">${esc(srcMetric('offerCount'))}</div><div class="lbl">🏷️ Active Offers</div></div>
        <div class="jpt-v2-metric"><div class="num" data-src="campaignCount">${esc(srcMetric('campaignCount'))}</div><div class="lbl">📣 Campaigns</div></div>
      </div>

      <div class="jpt-v2-section"><b>Quick Actions</b><span>Manage your restaurant</span></div>
      <div class="jpt-v2-actions">
        <button class="jpt-v2-action" data-p="orders"><b>🧾</b>Orders</button>
        <button class="jpt-v2-action" data-p="menu"><b>🍽️</b>Menu Manager</button>
        <button class="jpt-v2-action" data-p="images"><b>🖼️</b>Images</button>
        <button class="jpt-v2-action" data-p="offers"><b>🏷️</b>Offers</button>
        <button class="jpt-v2-action" data-p="campaigns"><b>📣</b>Campaigns</button>
        <button class="jpt-v2-action" data-p="finance"><b>▥</b>Finance</button>
        <button class="jpt-v2-action" data-p="reports"><b>▤</b>Reports</button>
        <button class="jpt-v2-action" data-p="settings"><b>⚙️</b>Settings</button>
      </div>

      <div class="jpt-v2-open"><span>🧾 View Open Orders</span><button data-p="orders">Open Orders →</button></div>
    `;

    // Keep the original functional controls, but place them inside the new premium header.
    moveControls(root);
    if(top)top.style.display='none';

    // Preserve original live IDs off-screen so existing business logic continues updating them.
    oldGrid.style.position='absolute';oldGrid.style.left='-100000px';oldGrid.style.width='1px';oldGrid.style.height='1px';oldGrid.style.overflow='hidden';oldGrid.style.opacity='0';
    oldHome.style.display='none';
    oldHero.style.display='none';

    const status=document.getElementById('statusBox');
    if(status){
      const host=root.querySelector('#jptV2StatusHost');
      host.appendChild(status);
      setLogo(status.querySelector('.store'));
    }

    root.querySelectorAll('[data-p]').forEach(b=>b.onclick=()=>{ if(typeof window.showPanel==='function')window.showPanel(b.dataset.p); });
    document.getElementById('jptV2Bell').onclick=()=>{ if(typeof window.showPanel==='function')window.showPanel('orders'); };
    let bottom=document.getElementById('jptV2Bottom');
    if(!bottom){
      bottom=document.createElement('nav');bottom.id='jptV2Bottom';bottom.className='jpt-v2-bottom';
      bottom.innerHTML='<button class="active" data-p="home"><b>⌂</b>Home</button><button data-p="orders"><b>🧾</b>Orders</button><button data-p="menu"><b>☰</b>Menu</button><button data-p="offers"><b>🏷️</b>Offers</button><button data-p="settings"><b>⚙️</b>Settings</button>';
      document.body.appendChild(bottom);
      bottom.querySelectorAll('button').forEach(b=>b.onclick=()=>{
        bottom.querySelectorAll('button').forEach(x=>x.classList.remove('active'));b.classList.add('active');
        if(b.dataset.p==='home')window.scrollTo({top:0,behavior:'smooth'});
        else if(typeof window.showPanel==='function')window.showPanel(b.dataset.p);
      });
    }

    const select=document.getElementById('outletSelect');
    if(select)select.addEventListener('change',()=>setTimeout(refresh,700),{once:false});
    bindPoster();
    sync();
  }

  let posterIndex=0;
  function bindPoster(){
    const img=document.getElementById('jptV2Poster'); if(!img)return;
    const dots=document.querySelectorAll('#'+ROOT+' .jpt-v2-dots i');
    const show=()=>{img.src=POSTERS[posterIndex];dots.forEach((d,i)=>d.classList.toggle('on',i===posterIndex));};
    document.getElementById('jptV2Prev').onclick=()=>{posterIndex=(posterIndex+POSTERS.length-1)%POSTERS.length;show()};
    document.getElementById('jptV2Next').onclick=()=>{posterIndex=(posterIndex+1)%POSTERS.length;show()};
    clearInterval(window.__jptV2PosterTimer);
    window.__jptV2PosterTimer=setInterval(()=>{posterIndex=(posterIndex+1)%POSTERS.length;show()},5000);
  }

  function sync(){
    const root=document.getElementById(ROOT);if(!root)return;
    ['ordersCount','menuCount','offerCount','campaignCount'].forEach(id=>{
      const el=root.querySelector('[data-src="'+id+'"]');const src=document.getElementById(id);if(el&&src)el.textContent=src.textContent.trim()||'—';
    });
    const status=document.getElementById('statusBox');
    if(status){
      const text=((document.getElementById('statusTitle')?.textContent||'')+' '+(document.getElementById('statusText')?.textContent||'')).toLowerCase();
      const online=status.classList.contains('online')||text.includes('online');
      status.classList.toggle('online',online);status.classList.toggle('offline',!online);
      setLogo(status.querySelector('.store'));
    }
  }

  async function refresh(){
    try{const outlet=await getOutlet();build(outlet);sync()}catch(e){console.warn('[JPT Final Touch V2]',e)}
  }

  function boot(){
    addStyle();
    setTimeout(refresh,1200);
    setInterval(sync,1200);
    window.addEventListener('jpt:outlet-changed',()=>setTimeout(refresh,500));
    window.addEventListener('jpt:outlet-data-refreshed',()=>setTimeout(refresh,500));
    window.addEventListener('jpt:branding-updated',()=>setTimeout(refresh,700));
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();
})();
